-- Forward-only retirement. Apply with the hardware-only backend release.
-- Keep earlier migration files unchanged: bootstrap verifies their checksums.
BEGIN;
SET LOCAL search_path=findi,pg_catalog;
CREATE TEMP TABLE retired_categories ON COMMIT DROP AS SELECT id FROM categories WHERE id='cat-repuestos-automotrices';
CREATE TEMP TABLE retired_subcategories ON COMMIT DROP AS SELECT id FROM subcategories WHERE category_id IN (SELECT id FROM retired_categories);
CREATE TEMP TABLE retired_families ON COMMIT DROP AS SELECT id FROM families WHERE subcategory_id IN (SELECT id FROM retired_subcategories);
CREATE TEMP TABLE retired_stores ON COMMIT DROP AS SELECT id FROM stores WHERE business_type <> 'ferreteria' OR api_payload->>'tipoNegocio' IN ('repuestos','desarmaduria');
CREATE TEMP TABLE retired_products ON COMMIT DROP AS SELECT id,name FROM products WHERE family_id IN (SELECT id FROM retired_families) OR api_payload->>'categoriaId'='cat-repuestos-automotrices' OR api_payload->>'ambitoComercial'='desarmaduria' OR automotive_identity IS NOT NULL OR CASE WHEN jsonb_typeof(api_payload->'compatibilidadVehiculos')='array' THEN jsonb_array_length(api_payload->'compatibilidadVehiculos') ELSE 0 END>0;
CREATE TEMP TABLE retired_offers ON COMMIT DROP AS SELECT id FROM offers WHERE product_id IN (SELECT id FROM retired_products) OR store_id IN (SELECT id FROM retired_stores) OR donor_vehicle_id IS NOT NULL;
CREATE TEMP TABLE retired_brands ON COMMIT DROP AS SELECT b.id FROM brands b WHERE (EXISTS(SELECT 1 FROM brand_uses u WHERE u.brand_id=b.id AND u.use_kind='vehiculo') OR EXISTS(SELECT 1 FROM products p WHERE p.brand_id=b.id AND p.id IN (SELECT id FROM retired_products))) AND NOT EXISTS(SELECT 1 FROM products p WHERE p.brand_id=b.id AND p.id NOT IN (SELECT id FROM retired_products));
CREATE TEMP TABLE retired_media ON COMMIT DROP AS SELECT asset_id id FROM product_media WHERE product_id IN (SELECT id FROM retired_products);
CREATE TEMP TABLE retired_rights ON COMMIT DROP AS SELECT rights_id id FROM product_content_rights WHERE product_id IN (SELECT id FROM retired_products) UNION SELECT a.rights_id FROM media_assets a JOIN retired_media m ON m.id=a.id WHERE a.rights_id IS NOT NULL;
-- Remove matching lines from mixed quotations; retain every hardware line.
CREATE TEMP TABLE affected_quotes ON COMMIT DROP AS SELECT DISTINCT quotation_id id FROM quotation_items WHERE product_id IN (SELECT id FROM retired_products) OR product_reference IN (SELECT id FROM retired_products) OR lower(product_name_snapshot) IN (SELECT lower(name) FROM retired_products) OR selected_offer_id IN (SELECT id FROM retired_offers) OR selected_store_id IN (SELECT id FROM retired_stores);
DELETE FROM quotation_items WHERE quotation_id IN (SELECT id FROM affected_quotes) AND (product_id IN (SELECT id FROM retired_products) OR product_reference IN (SELECT id FROM retired_products) OR lower(product_name_snapshot) IN (SELECT lower(name) FROM retired_products) OR selected_offer_id IN (SELECT id FROM retired_offers) OR selected_store_id IN (SELECT id FROM retired_stores));
UPDATE quotations q SET api_payload=jsonb_set(coalesce(q.api_payload,'{}'),'{items}',coalesce((SELECT jsonb_agg(item ORDER BY ordinal) FROM jsonb_array_elements(coalesce(q.api_payload->'items','[]')) WITH ORDINALITY AS rows(item,ordinal) WHERE lower(coalesce(item->>'productName','')) NOT IN (SELECT lower(name) FROM retired_products) AND coalesce(item->>'productoMaestroId','') NOT IN (SELECT id FROM retired_products) AND coalesce(item->>'productoFerreteriaId','') NOT IN (SELECT id FROM retired_offers) AND coalesce(item->>'storeId','') NOT IN (SELECT id FROM retired_stores)),'[]')) - 'quotation' - 'cotizacion',updated_at=now() WHERE q.id IN (SELECT id FROM affected_quotes);
UPDATE quotations SET single_store_id=NULL,single_store_reference=NULL,single_store_name_snapshot=NULL,api_payload=api_payload - ARRAY['singleStoreId','singleStoreName','ferreteriaUnicaId','ferreteriaUnica'] WHERE single_store_id IN (SELECT id FROM retired_stores);
UPDATE quotations q SET api_payload=jsonb_set(q.api_payload - 'verificationCode','{pricingOffers}',coalesce((SELECT jsonb_agg(offer ORDER BY ordinal) FROM jsonb_array_elements(coalesce(q.api_payload->'pricingOffers','[]')) WITH ORDINALITY AS rows(offer,ordinal) WHERE lower(coalesce(offer->>'productName','')) NOT IN (SELECT lower(name) FROM retired_products) AND coalesce(offer->>'productoMaestroId','') NOT IN (SELECT id FROM retired_products) AND coalesce(offer->>'productoFerreteriaId','') NOT IN (SELECT id FROM retired_offers) AND coalesce(offer->>'storeId','') NOT IN (SELECT id FROM retired_stores)),'[]')) WHERE q.id IN (SELECT id FROM affected_quotes) OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(q.api_payload->'pricingOffers','[]')) offer WHERE lower(offer->>'productName') IN (SELECT lower(name) FROM retired_products) OR offer->>'productoMaestroId' IN (SELECT id FROM retired_products) OR offer->>'storeId' IN (SELECT id FROM retired_stores));
-- Frozen verifications are deleted as whole documents so no price is rewritten.
ALTER TABLE quotation_verifications DISABLE TRIGGER immutable_verification;
DELETE FROM quotation_verifications WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(store_lines) line WHERE lower(line->>'productName') IN (SELECT lower(name) FROM retired_products) OR line->>'productId' IN (SELECT id FROM retired_products) OR line->>'storeId' IN (SELECT id FROM retired_stores));
ALTER TABLE quotation_verifications ENABLE TRIGGER immutable_verification;
CREATE TEMP TABLE retired_requests ON COMMIT DROP AS SELECT id FROM product_requests WHERE store_id IN (SELECT id FROM retired_stores) OR suggested_product_id IN (SELECT id FROM retired_products) OR resulting_offer_id IN (SELECT id FROM retired_offers) OR api_payload ? 'vehiculoDonanteId';
DELETE FROM import_rows WHERE resulting_request_id IN (SELECT id FROM retired_requests);
DELETE FROM product_requests WHERE id IN (SELECT id FROM retired_requests);
DELETE FROM offer_history WHERE store_reference IN (SELECT id FROM retired_stores) OR offer_reference IN (SELECT id FROM retired_offers) OR product_id IN (SELECT id FROM retired_products) OR product_reference IN (SELECT id FROM retired_products) OR offer_id IN (SELECT id FROM retired_offers) OR store_id IN (SELECT id FROM retired_stores);
DELETE FROM price_reports WHERE store_reference IN (SELECT id FROM retired_stores) OR offer_reference IN (SELECT id FROM retired_offers) OR product_id IN (SELECT id FROM retired_products) OR offer_id IN (SELECT id FROM retired_offers) OR store_id IN (SELECT id FROM retired_stores);
DELETE FROM ip_reports WHERE product_id IN (SELECT id FROM retired_products) OR offer_id IN (SELECT id FROM retired_offers) OR store_id IN (SELECT id FROM retired_stores);
DELETE FROM store_agreements WHERE store_id IN (SELECT id FROM retired_stores) OR store_reference IN (SELECT id FROM retired_stores);
DELETE FROM import_batches WHERE store_id IN (SELECT id FROM retired_stores);
DELETE FROM import_rows WHERE resulting_offer_id IN (SELECT id FROM retired_offers);
DELETE FROM store_daily_top_products WHERE product_id IN (SELECT id FROM retired_products) OR product_reference IN (SELECT id FROM retired_products);
-- SEO routes are derived and rebuilt; clear aliases as well as canonical rows.
DELETE FROM seo_routes;
DELETE FROM public_cache_artifacts;
DELETE FROM catalog_search_documents;
DELETE FROM offers WHERE id IN (SELECT id FROM retired_offers);
DROP TRIGGER offer_donor_store ON offers;
ALTER TABLE offers DROP COLUMN donor_vehicle_id, DROP COLUMN donor_item_id;
DROP FUNCTION check_donor_offer();
DROP TABLE donor_vehicles;
DROP TABLE offer_vehicle_applications;
DROP TABLE product_vehicle_applications;
DROP TABLE vehicle_models;
DELETE FROM products WHERE id IN (SELECT id FROM retired_products);
DELETE FROM media_assets WHERE id IN (SELECT id FROM retired_media) AND NOT EXISTS(SELECT 1 FROM product_media m WHERE m.asset_id=media_assets.id);
DELETE FROM content_rights WHERE id IN (SELECT id FROM retired_rights) AND NOT EXISTS(SELECT 1 FROM media_assets a WHERE a.rights_id=content_rights.id) AND NOT EXISTS(SELECT 1 FROM product_content_rights p WHERE p.rights_id=content_rights.id);
DELETE FROM stores WHERE id IN (SELECT id FROM retired_stores);
DELETE FROM product_models WHERE family_id IN (SELECT id FROM retired_families);
DELETE FROM attribute_definitions WHERE family_id IN (SELECT id FROM retired_families);
DELETE FROM families WHERE id IN (SELECT id FROM retired_families);
DELETE FROM subcategories WHERE id IN (SELECT id FROM retired_subcategories);
DELETE FROM categories WHERE id IN (SELECT id FROM retired_categories);
DELETE FROM brands WHERE id IN (SELECT id FROM retired_brands);
DELETE FROM brand_uses WHERE use_kind <> 'fabricante';
UPDATE brands SET api_payload=jsonb_set(api_payload,'{usos}','["fabricante"]');
UPDATE families SET api_payload=api_payload - 'permiteVehiculos';
UPDATE products SET api_payload=(api_payload - ARRAY['nombrePieza','detalleVariante','compatibilidadVehiculos','compatibilidadReferencial']) || '{"ambitoComercial":"ferreteria"}';
UPDATE offers SET api_payload=api_payload - ARRAY['vehiculoDonanteId','piezaDonanteId','asociacionesVehiculos','vehiculosEditables'];
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE products DROP COLUMN part_name,DROP COLUMN variant_label,DROP COLUMN automotive_identity;
ALTER TABLE families DROP COLUMN supports_vehicle_applications;
ALTER TABLE stores DROP CONSTRAINT stores_business_type_check;
ALTER TABLE stores ADD CONSTRAINT stores_business_type_check CHECK(business_type='ferreteria');
ALTER TABLE brand_uses DROP CONSTRAINT brand_uses_use_kind_check;
ALTER TABLE brand_uses ADD CONSTRAINT brand_uses_use_kind_check CHECK(use_kind='fabricante');
CREATE UNIQUE INDEX offers_store_product ON offers(store_id,product_id);
UPDATE catalog_revisions SET revision=revision+1,changed_at=now();
COMMIT;
